<?php require_once __DIR__.'/../includes/bootstrap.php';if(!is_admin()){header('Location: ../login.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare("UPDATE reviews SET is_approved=? WHERE id=?")->execute([(int)$_POST['approve'],(int)$_POST['id']]);}$reviews=$pdo->query("SELECT r.*,u.full_name,p.name product_name FROM reviews r JOIN users u ON u.id=r.user_id JOIN products p ON p.id=r.product_id ORDER BY r.created_at DESC")->fetchAll();$pageTitle='مدیریت دیدگاه‌ها';include __DIR__.'/../includes/header.php';?><main class="page-content container"><h1 class="page-title">بررسی دیدگاه‌ها</h1><div class="table-wrap"><table class="data-table"><tr><th>کاربر</th><th>محصول</th><th>دیدگاه</th><th>وضعیت</th><th>عملیات</th></tr><?php foreach($reviews as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['product_name'])?></td><td><?=e($r['body'])?></td><td><?=$r['is_approved']?'تأییدشده':'در انتظار'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="approve" value="1"><button>تأیید</button></form></td></tr><?php endforeach;?></table></div></main><?php include __DIR__.'/../includes/footer.php';?>
